ALTER TABLE equipment_tickets ADD COLUMN priority text NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low','Normal','High','Urgent'));
CREATE TABLE ticket_attachments(company_id uuid NOT NULL,ticket_id uuid NOT NULL,id uuid NOT NULL,filename text NOT NULL CHECK(length(filename) BETWEEN 1 AND 200),content bytea NOT NULL CHECK(octet_length(content) BETWEEN 1 AND 10485760),uploader_user_id uuid NOT NULL REFERENCES users(id),uploader_name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,ticket_id,id),FOREIGN KEY(company_id,ticket_id) REFERENCES equipment_tickets(company_id,id));
